mcq(1,800,'The term pole in filter terminology refers to','Thuật ngữ “cực” (pole) trong kỹ thuật lọc chỉ',[('a high-gain op-amp','một op-amp độ lợi cao'),('one complete active filter','một bộ lọc tích cực hoàn chỉnh'),('a single RC circuit','một mạch RC đơn'),('the feedback circuit','mạch hồi tiếp')],2,'Each RC circuit in the frequency-selective network is one pole.','Mỗi mạch RC trong mạng chọn tần là một cực.','basic')
mcq(2,800,'A single resistor and a single capacitor can be connected to form a filter with a roll-off rate of','Một điện trở và một tụ điện có thể tạo bộ lọc có tốc độ suy giảm',[('−20 dB/decade','−20 dB/decade'),('−40 dB/decade','−40 dB/decade'),('−6 dB/octave','−6 dB/octave'),('answers (a) and (c)','đáp án (a) và (c)')],3,'One pole rolls off at −20 dB/decade, which is the same slope as −6 dB/octave.','Một cực suy giảm −20 dB/decade, cùng độ dốc với −6 dB/octave.','basic',1,True)
mcq(3,800,'A band-pass response has','Đáp ứng thông dải có',[('two critical frequencies','hai tần số tới hạn'),('one critical frequency','một tần số tới hạn'),('a flat curve in the passband','đường cong phẳng trong dải thông'),('a wide bandwidth','băng thông rộng')],0,'A lower and an upper critical frequency bound the passband.','Tần số tới hạn dưới và trên giới hạn dải thông.','basic')
mcq(4,800,'The lowest frequency passed by a low-pass filter is','Tần số thấp nhất mà bộ lọc thông thấp cho qua là',[('1 Hz','1 Hz'),('0 Hz','0 Hz'),('10 Hz','10 Hz'),('dependent on the critical frequency','phụ thuộc tần số tới hạn')],1,'A low-pass filter passes dc (0 Hz) up to its critical frequency.','Bộ lọc thông thấp cho qua từ một chiều (0 Hz) đến tần số tới hạn.','lp')
mcq(5,800,'The quality factor (Q) of a band-pass filter depends on','Hệ số phẩm chất (Q) của bộ lọc thông dải phụ thuộc vào',[('the critical frequencies','các tần số tới hạn'),('only the bandwidth','chỉ băng thông'),('the center frequency and the bandwidth','tần số trung tâm và băng thông'),('only the center frequency','chỉ tần số trung tâm')],2,'Q = f0/BW.','Q = f0/BW.','bp')
mcq(6,800,'The damping factor of an active filter determines','Hệ số tắt dần của bộ lọc tích cực quyết định',[('the voltage gain','độ lợi điện áp'),('the critical frequency','tần số tới hạn'),('the response characteristic','đặc tính đáp ứng'),('the roll-off rate','tốc độ suy giảm')],2,'DF sets whether the response is Butterworth, Chebyshev or Bessel.','DF quyết định đáp ứng là Butterworth, Chebyshev hay Bessel.','chr')
mcq(7,800,'A maximally flat frequency response is known as','Đáp ứng tần số phẳng tối đa được gọi là',[('Chebyshev','Chebyshev'),('Butterworth','Butterworth'),('Bessel','Bessel'),('Colpitts','Colpitts')],1,'Butterworth: flat passband (Colpitts is an oscillator).','Butterworth: dải thông phẳng (Colpitts là mạch dao động).','chr')
mcq(8,800,'The damping factor of a filter is set by','Hệ số tắt dần của bộ lọc được đặt bởi',[('the negative feedback circuit','mạch hồi tiếp âm'),('the positive feedback circuit','mạch hồi tiếp dương'),('the frequency-selective circuit','mạch chọn tần'),('the gain of the op-amp','độ lợi của op-amp')],0,'DF = 2 − R1/R2 for the Sallen-Key stage: set by the negative-feedback divider.','DF = 2 − R1/R2 cho tầng Sallen-Key: do bộ chia hồi tiếp âm đặt.','chr')
mcq(9,800,'The number of poles in a filter affect the','Số cực của bộ lọc ảnh hưởng đến',[('voltage gain','độ lợi điện áp'),('bandwidth','băng thông'),('center frequency','tần số trung tâm'),('roll-off rate','tốc độ suy giảm')],3,'Roll-off = −20 dB/decade per pole.','Tốc độ suy giảm = −20 dB/decade mỗi cực.','basic')
mcq(10,801,'Sallen-Key low-pass filters are','Bộ lọc thông thấp Sallen-Key là',[('single-pole filters','bộ lọc một cực'),('second-order filters','bộ lọc bậc hai'),('Butterworth filters','bộ lọc Butterworth'),('band-pass filters','bộ lọc thông dải')],1,'The basic Sallen-Key stage has two RC sections: two poles.','Tầng Sallen-Key cơ bản có hai khâu RC: hai cực.','lp')
mcq(11,801,'When low-pass filters are cascaded, the roll-off rate','Khi ghép tầng các bộ lọc thông thấp, tốc độ suy giảm',[('increases','tăng'),('decreases','giảm'),('does not change','không đổi')],0,'Poles add: two 2-pole stages give −80 dB/decade.','Các cực cộng lại: hai tầng 2 cực cho −80 dB/decade.','lp')
mcq(12,801,'In a high-pass filter, the roll-off occurs','Ở bộ lọc thông cao, sự suy giảm xảy ra',[('above the critical frequency','phía trên tần số tới hạn'),('below the critical frequency','phía dưới tần số tới hạn'),('during the mid range','trong vùng giữa'),('at the center frequency','tại tần số trung tâm')],1,'Frequencies below fc are attenuated.','Các tần số dưới fc bị suy giảm.','hp')
mcq(13,801,'A two-pole Sallen-Key high-pass filter contains','Bộ lọc thông cao Sallen-Key hai cực gồm',[('one capacitor and two resistors','một tụ điện và hai điện trở'),('two capacitors and two resistors','hai tụ điện và hai điện trở'),('a feedback circuit','một mạch hồi tiếp'),('answers (b) and (c)','đáp án (b) và (c)')],3,'Two RC sections (two C, two R) plus the R1/R2 feedback divider.','Hai khâu RC (hai C, hai R) cộng bộ chia hồi tiếp R1/R2.','hp',1,True)
mcq(14,801,'When a low-pass and a high-pass filter are cascaded to get a band-pass filter, the critical frequency of the low-pass filter must be','Khi ghép tầng bộ lọc thông thấp và thông cao để được bộ lọc thông dải, tần số tới hạn của bộ lọc thông thấp phải',[('equal to the critical frequency of the high-pass filter','bằng tần số tới hạn của bộ lọc thông cao'),('less than the critical frequency of the high-pass filter','nhỏ hơn tần số tới hạn của bộ lọc thông cao'),('greater than the critical frequency of the high-pass filter','lớn hơn tần số tới hạn của bộ lọc thông cao')],2,'The passband lies between the high-pass fc (lower edge) and the low-pass fc (upper edge), so the low-pass fc must be greater.','Dải thông nằm giữa fc của thông cao (biên dưới) và fc của thông thấp (biên trên) nên fc thông thấp phải lớn hơn.','bp',2)
mcq(15,801,'A state-variable filter consists of','Bộ lọc biến trạng thái gồm',[('one op-amp with multiple-feedback paths','một op-amp với nhiều đường hồi tiếp'),('a summing amplifier and two integrators','một mạch cộng và hai mạch tích phân'),('a summing amplifier and two differentiators','một mạch cộng và hai mạch vi phân'),('three Butterworth stages','ba tầng Butterworth')],1,'A summing stage feeds two cascaded integrators in a feedback loop.','Một tầng cộng cấp cho hai mạch tích phân nối tiếp trong vòng hồi tiếp.','bp')
mcq(16,801,'When the gain of a filter is minimum at its center frequency, it is','Khi độ lợi của bộ lọc cực tiểu tại tần số trung tâm thì đó là',[('a band-pass filter','bộ lọc thông dải'),('a band-stop filter','bộ lọc chắn dải'),('a notch filter','bộ lọc notch'),('answers (b) and (c)','đáp án (b) và (c)')],3,'A band-stop (notch) filter has its minimum gain at f0.','Bộ lọc chắn dải (notch) có độ lợi cực tiểu tại f0.','bp',1,True)
T = [(1,'The response of a filter can be identified by its passband.','Đáp ứng của bộ lọc có thể nhận biết qua dải thông của nó.',1,'Low-pass, high-pass, band-pass and band-stop are named by their passband.','Thông thấp, thông cao, thông dải, chắn dải được gọi tên theo dải thông.','basic'),
 (2,'A filter pole is the cutoff frequency of a filter.','Cực của bộ lọc là tần số cắt của bộ lọc.',0,'A pole is one RC circuit, not a frequency.','Cực là một mạch RC, không phải một tần số.','basic'),
 (3,'A single-pole filter has one RC circuit.','Bộ lọc một cực có một mạch RC.',1,'By definition.','Theo định nghĩa.','basic'),
 (4,'A single-pole filter produces a roll-off of −25 dB/decade.','Bộ lọc một cực cho độ suy giảm −25 dB/decade.',0,'It is −20 dB/decade.','Là −20 dB/decade.','basic'),
 (5,'A low-pass filter can pass a dc voltage.','Bộ lọc thông thấp có thể cho điện áp một chiều đi qua.',1,'Its passband starts at 0 Hz.','Dải thông của nó bắt đầu từ 0 Hz.','lp'),
 (6,'A high-pass filter passes any frequency above dc.','Bộ lọc thông cao cho qua mọi tần số trên mức một chiều.',0,'It passes only frequencies above its critical frequency; those between dc and fc are attenuated.','Nó chỉ cho qua các tần số trên tần số tới hạn; tần số từ 0 đến fc bị suy giảm.','hp'),
 (7,'The critical frequency of a filter depends only on R and C values.','Tần số tới hạn của bộ lọc chỉ phụ thuộc vào giá trị R và C.',1,'Floyd: fc = 1/(2πRC) (single pole) or 1/(2π√(RA·RB·CA·CB)) (Sallen-Key); the gain network sets the damping, not fc.','Floyd: fc = 1/(2πRC) (một cực) hoặc 1/(2π√(RA·RB·CA·CB)) (Sallen-Key); mạng đặt độ lợi chỉ quyết định hệ số tắt dần, không quyết định fc.','basic'),
 (8,'The band-pass filter has two critical frequencies.','Bộ lọc thông dải có hai tần số tới hạn.',1,'Lower and upper.','Dưới và trên.','bp'),
 (9,'The quality factor of a band-pass filter is the ratio of bandwidth to the center frequency.','Hệ số phẩm chất của bộ lọc thông dải là tỉ số băng thông trên tần số trung tâm.',0,'Q = f0/BW: center frequency over bandwidth.','Q = f0/BW: tần số trung tâm chia băng thông.','bp'),
 (10,'The higher the Q, the narrower the bandwidth of a band-pass filter.','Q càng cao thì băng thông bộ lọc thông dải càng hẹp.',1,'BW = f0/Q.','BW = f0/Q.','bp'),
 (11,'The Butterworth characteristic provides a flat response in the passband.','Đặc tính Butterworth cho đáp ứng phẳng trong dải thông.',1,'Maximally flat.','Phẳng tối đa.','chr'),
 (12,'Filters with a Chebyshev response have a slow roll-off.','Bộ lọc có đáp ứng Chebyshev có độ suy giảm chậm.',0,'Chebyshev has a faster roll-off than Butterworth, at the price of passband ripple.','Chebyshev suy giảm nhanh hơn Butterworth, đổi lại có gợn trong dải thông.','chr'),
 (13,'A Chebyshev response has ripples in the passband.','Đáp ứng Chebyshev có gợn trong dải thông.',1,'That is its characteristic.','Đó là đặc trưng của nó.','chr'),
 (14,'Bessel filters are useful in filtering pulse waveforms.','Bộ lọc Bessel hữu ích để lọc các dạng xung.',1,'Linear phase keeps the pulse shape.','Pha tuyến tính giữ nguyên dạng xung.','chr'),
 (15,'The order of a filter is the number of poles it contains.','Bậc của bộ lọc là số cực mà nó có.',1,'By definition.','Theo định nghĩa.','basic'),
 (16,'A Sallen-Key filter is also known as a VCVS filter.','Bộ lọc Sallen-Key còn gọi là bộ lọc VCVS.',1,'Voltage-controlled voltage source.','Nguồn áp điều khiển bằng áp.','lp'),
 (17,'Multiple feedback is used in low-pass filters.','Hồi tiếp nhiều đường được dùng trong bộ lọc thông thấp.',0,'Floyd uses the multiple-feedback topology for band-pass filters.','Floyd dùng cấu hình hồi tiếp nhiều đường cho bộ lọc thông dải.','bp'),
 (18,'A state-variable filter uses differentiators.','Bộ lọc biến trạng thái dùng các mạch vi phân.',0,'It uses a summing amplifier and two integrators.','Nó dùng một mạch cộng và hai mạch tích phân.','bp'),
 (19,'A band-stop filter rejects certain frequencies.','Bộ lọc chắn dải loại bỏ một số tần số nhất định.',1,'It attenuates a band around f0.','Nó làm suy giảm một dải quanh f0.','bp'),
 (20,'Filter response can be measured using a sweep generator.','Có thể đo đáp ứng bộ lọc bằng máy phát quét tần.',1,'A sweep generator with a scope or analyzer displays the response curve.','Máy phát quét tần cùng dao động ký hoặc máy phân tích hiển thị đường đáp ứng.','basic')]
